"use client"

import { useState } from "react"

import { cn } from "@/lib/utils"

import { SWEEP, type SweepPoint } from "./sweep-data"

// My cache simulation of the paper's coding-agent workload, one line per policy.
//
// The numbers are generated by sim.py (described in the article): the
// SemiAnalysis Claude Code traces replayed as N closed sessions against
// GLM-5.3-Flash's per-GPU cache in the paper's units (2,531 blocks of 4,352
// tokens, five blocks per checkpoint), measured over minutes 15-45 of a 45-minute
// replay, averaged over two seeds. It models the cache, not the GPU: no
// throughput or latency here.

type MetricKey = "hit_rate" | "uncached_p50" | "redundant_per_req" | "user_cost_per_M"

const METRICS: { key: MetricKey; label: string; fmt: (v: number) => string; better: "up" | "down" }[] = [
  { key: "hit_rate", label: "token hit rate", fmt: (v) => `${(v * 100).toFixed(1)}%`, better: "up" },
  { key: "uncached_p50", label: "median uncached tokens", fmt: (v) => (v >= 1e4 ? `${(v / 1e3).toFixed(0)}K` : v >= 1e3 ? `${(v / 1e3).toFixed(1)}K` : v.toFixed(0)), better: "down" },
  { key: "redundant_per_req", label: "redundant prefill / request", fmt: (v) => (v >= 1e3 ? `${(v / 1e3).toFixed(1)}K` : v.toFixed(0)), better: "down" },
  { key: "user_cost_per_M", label: "user cost / 1M input", fmt: (v) => `$${v.toFixed(3)}`, better: "down" },
]

const POLICIES: { key: string; label: string; color: string; dash?: string }[] = [
  { key: "vllm", label: "vLLM-like", color: "oklch(0.62 0.17 45)" },
  { key: "asc_lru", label: "+ASC, LRU per block", color: "oklch(0.60 0.19 25)", dash: "4 3" },
  { key: "asc_unit", label: "ASC + whole-state LRU", color: "oklch(0.55 0.12 300)" },
  { key: "flashstate", label: "FlashState, Eq. 7", color: "oklch(0.60 0.15 255)", dash: "2 2" },
  { key: "fs_leaf", label: "FlashState, leaf-last", color: "oklch(0.55 0.16 155)" },
]

export function PolicySweep() {
  const [metric, setMetric] = useState<MetricKey>("hit_rate")
  const [hidden, setHidden] = useState<Record<string, boolean>>({})
  const m = METRICS.find((x) => x.key === metric) ?? METRICS[0]

  const sessions = Array.from(new Set(Object.values(SWEEP).flatMap((d) => Object.keys(d).map(Number)))).sort((a, b) => a - b)
  const vals: number[] = []
  for (const p of POLICIES) {
    const d = SWEEP[p.key]
    if (!d || hidden[p.key]) continue
    for (const n of sessions) if (d[n]) vals.push(d[n][metric])
  }
  const lo = 0
  const hi = metric === "hit_rate" ? 1 : Math.max(...vals, 1e-9) * 1.08

  const W = 700
  const H = 250
  const X0 = 64
  const X1 = W - 150
  const Y0 = 18
  const Y1 = H - 34
  const xs = (n: number) => X0 + ((n - sessions[0]) / (sessions[sessions.length - 1] - sessions[0])) * (X1 - X0)
  const ys = (v: number) => Y1 - ((v - lo) / (hi - lo)) * (Y1 - Y0)
  const ticks = [0, 0.25, 0.5, 0.75, 1].map((t) => lo + t * (hi - lo))

  const at48 = (k: string): SweepPoint | undefined => SWEEP[k]?.[48]

  return (
    <figure className="my-8 overflow-hidden rounded-xl border bg-gradient-to-b from-muted/15 to-transparent">
      <div className="flex flex-wrap items-center justify-between gap-2 border-b px-4 py-2.5">
        <span className="font-mono text-xs text-muted-foreground">my simulation · GLM-5.3-Flash cache per GPU · SemiAnalysis traces</span>
        <span className="font-mono text-[10px] text-muted-foreground">{m.better === "up" ? "higher is better" : "lower is better"}</span>
      </div>
      <div className="p-3 sm:p-4">
        <div className="flex flex-wrap gap-1.5">
          {METRICS.map((x) => (
            <button
              key={x.key}
              type="button"
              onClick={() => setMetric(x.key)}
              aria-pressed={metric === x.key}
              className={cn(
                "cursor-pointer rounded-full border px-2.5 py-1 font-mono text-[10px] transition-colors",
                metric === x.key ? "border-foreground/30 bg-muted/50 text-foreground" : "border-border text-muted-foreground hover:text-foreground",
              )}
            >
              {x.label}
            </button>
          ))}
        </div>

        <div className="mt-2 overflow-x-auto">
          <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H} role="img" className="min-w-[660px] max-w-full">
            <title>
              {`${m.label} against concurrent sessions for five cache policies in my simulation. At 48 sessions: ${POLICIES.map((p) => `${p.label} ${at48(p.key) ? m.fmt(at48(p.key)![metric]) : "n/a"}`).join(", ")}.`}
            </title>
            {ticks.map((t) => (
              <g key={t}>
                <line x1={X0} x2={X1} y1={ys(t)} y2={ys(t)} stroke="currentColor" strokeOpacity={0.08} />
                <text x={X0 - 6} y={ys(t) + 3} fontSize={8} textAnchor="end" fill="currentColor" fillOpacity={0.5} fontFamily="ui-monospace, monospace">
                  {m.fmt(t)}
                </text>
              </g>
            ))}
            {sessions.map((n) => (
              <text key={n} x={xs(n)} y={Y1 + 14} fontSize={8} textAnchor="middle" fill="currentColor" fillOpacity={0.5} fontFamily="ui-monospace, monospace">
                {n}
              </text>
            ))}
            <text x={(X0 + X1) / 2} y={H - 4} fontSize={8} textAnchor="middle" fill="currentColor" fillOpacity={0.5} fontFamily="ui-monospace, monospace">
              concurrent sessions
            </text>
            {POLICIES.map((p) => {
              const d = SWEEP[p.key]
              if (!d || hidden[p.key]) return null
              const pts = sessions.filter((n) => d[n]).map((n) => [xs(n), ys(d[n][metric])] as const)
              const last = pts[pts.length - 1]
              return (
                <g key={p.key}>
                  <polyline points={pts.map(([a, b]) => `${a.toFixed(1)},${b.toFixed(1)}`).join(" ")} fill="none" stroke={p.color} strokeWidth={1.8} strokeDasharray={p.dash} />
                  {pts.map(([a, b], i) => (
                    <circle key={i} cx={a} cy={b} r={2.4} fill={p.color} />
                  ))}
                  {last ? (
                    <text x={X1 + 8} y={last[1] + 3} fontSize={8} fill={p.color} fontFamily="ui-monospace, monospace">
                      {p.label}
                    </text>
                  ) : null}
                </g>
              )
            })}
          </svg>
        </div>

        <div className="mt-2 flex flex-wrap gap-1.5">
          {POLICIES.map((p) => (
            <button
              key={p.key}
              type="button"
              onClick={() => setHidden((h) => ({ ...h, [p.key]: !h[p.key] }))}
              aria-pressed={!hidden[p.key]}
              className={cn(
                "cursor-pointer rounded-full border px-2.5 py-1 font-mono text-[10px] transition-colors",
                hidden[p.key] ? "border-border text-muted-foreground line-through" : "border-foreground/30 text-foreground",
              )}
              style={{ color: hidden[p.key] ? undefined : p.color }}
            >
              {p.label}
            </button>
          ))}
        </div>
      </div>
      <figcaption className="border-t px-4 py-2 text-xs text-muted-foreground">
        Measured in my simulator, not on a GPU: two seeds per point, minutes 15–45 of each 45-minute replay. User cost applies the demo&apos;s list prices to the simulated hit rate. Labels sit at each line&apos;s last point, so two close lines can overlap; click a policy to hide it.
      </figcaption>
    </figure>
  )
}
